-- Create "knowledge_documents" table
CREATE TABLE `knowledge_documents` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `space_id` varchar(32) NOT NULL, `folder_id` varchar(32) NOT NULL DEFAULT "", `title` varchar(480) NOT NULL, `current_version` bigint NOT NULL, `updated_at` datetime(6) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `knowledgedocument_space_id_folder_id_title` (`space_id`, `folder_id`, `title`), INDEX `knowledgedocument_team_id_updated_at` (`team_id`, `updated_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "knowledge_folders" table
CREATE TABLE `knowledge_folders` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `space_id` varchar(32) NOT NULL, `parent_id` varchar(32) NOT NULL DEFAULT "", `name` varchar(320) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `knowledgefolder_space_id_parent_id_name` (`space_id`, `parent_id`, `name`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "knowledge_proposals" table
CREATE TABLE `knowledge_proposals` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `document_id` varchar(32) NOT NULL, `base_version` bigint NOT NULL, `author_id` varchar(32) NOT NULL, `source` enum('console','agent') NOT NULL, `computer` varchar(256) NOT NULL DEFAULT "", `session_id` varchar(128) NOT NULL DEFAULT "", `note` varchar(800) NOT NULL DEFAULT "", `text` longtext NOT NULL, `state` enum('pending','accepted','declined','withdrawn') NOT NULL DEFAULT "pending", `decided_by` varchar(32) NOT NULL DEFAULT "", `decided_at` datetime(6) NULL, `reason` varchar(2000) NOT NULL DEFAULT "", `version` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `knowledgeproposal_document_id_state` (`document_id`, `state`), INDEX `knowledgeproposal_team_id_state_created_at` (`team_id`, `state`, `created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "knowledge_spaces" table
CREATE TABLE `knowledge_spaces` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `name` varchar(320) NOT NULL, `reading` enum('team','members') NOT NULL DEFAULT "team", `created_by` varchar(32) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `knowledgespace_team_id_name` (`team_id`, `name`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "knowledge_space_members" table
CREATE TABLE `knowledge_space_members` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `space_id` varchar(32) NOT NULL, `user_id` varchar(32) NOT NULL, `role` enum('reader','editor') NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `knowledgespacemember_space_id_user_id` (`space_id`, `user_id`), INDEX `knowledgespacemember_user_id` (`user_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "knowledge_versions" table
CREATE TABLE `knowledge_versions` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `document_id` varchar(32) NOT NULL, `number` bigint NOT NULL, `author_id` varchar(32) NOT NULL, `source` enum('console','agent') NOT NULL, `note` varchar(800) NOT NULL DEFAULT "", `text` longtext NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `knowledgeversion_document_id_number` (`document_id`, `number`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
